<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT e.*,c.nome cliente,c.telefone,c.email,u.nome usuario_nome FROM encomendas e JOIN clientes c ON c.id=e.cliente_id LEFT JOIN usuarios u ON u.id=e.usuario_id WHERE e.id=?');$st->execute([$id]);$eRow=$st->fetch();if(!$eRow)exit('Encomenda não encontrada.');
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$new=$_POST['status']??'';if(in_array($new,['Aberta','Aguardando','Confirmada','Em preparação','Pronta','Entregue','Cancelada'],true)&&$new!==$eRow['status']){$pdo->prepare('UPDATE encomendas SET status=? WHERE id=?')->execute([$new,$id]);$pdo->prepare('INSERT INTO encomenda_status_historico(encomenda_id,status_anterior,status_novo,usuario_id,data_hora) VALUES(?,?,?,?,?)')->execute([$id,$eRow['status'],$new,current_user()['id'],now()]);log_action('alteração de status','encomendas',$id,$eRow['status'].' -> '.$new);flash('success','Status atualizado.');redirect('detalhes.php?id='.$id);}}
$it=$pdo->prepare('SELECT ei.*,p.nome FROM encomenda_itens ei JOIN produtos p ON p.id=ei.produto_id WHERE ei.encomenda_id=?');$it->execute([$id]);$items=$it->fetchAll();$hist=$pdo->prepare('SELECT h.*,u.nome usuario_nome FROM encomenda_status_historico h LEFT JOIN usuarios u ON u.id=h.usuario_id WHERE h.encomenda_id=? ORDER BY h.id');$hist->execute([$id]);$history=$hist->fetchAll();include __DIR__.'/../../includes/header.php'; ?><div class="no-print page-head"><div><h1>Encomenda <?=e($eRow['numero'])?></h1><div><?=status_badge($eRow['status'])?></div></div><div class="actions"><a class="btn primary" href="<?=e(app_url('/admin/pdv/index.php'))?>?from_encomenda=<?=$id?>">Converter em venda</a><a class="btn secondary" href="imprimir.php?id=<?=$id?>">Imprimir</a></div></div><div class="grid grid-2"><div class="card"><h3>Dados</h3><p><strong>Cliente:</strong> <?=e($eRow['cliente'])?></p><p><strong>Origem:</strong> <?=e($eRow['origem'])?></p><p><strong>Data:</strong> <?=datetime_br($eRow['data_hora'])?></p><p><strong>Usuário responsável:</strong> <?=e($eRow['usuario_nome'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Status</label><select name="status"><?php foreach(['Aberta','Aguardando','Confirmada','Em preparação','Pronta','Entregue','Cancelada'] as $s): ?><option <?=$eRow['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div><button class="btn primary" style="margin-top:8px">Atualizar status</button></form><p><strong>Observações:</strong><br><?=nl2br(e($eRow['observacoes']))?></p></div><div class="card"><h3>Itens</h3><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=e($i['nome'])?></td><td><?=e($i['quantidade'])?></td><td><?=money($i['preco_unitario'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><div class="total-line total"><span>Total</span><strong><?=money($eRow['total'])?></strong></div></div></div><div class="card" style="margin-top:16px"><h3>Histórico de status</h3><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Anterior</th><th>Novo</th><th>Usuário</th></tr></thead><tbody><?php foreach($history as $h): ?><tr><td><?=datetime_br($h['data_hora'])?></td><td><?=e($h['status_anterior']??'—')?></td><td><?=e($h['status_novo'])?></td><td><?=e($h['usuario_nome']??'—')?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
